#include <bits/stdc++.h>
using namespace std;
int main() {
    string s, t;
    cin >> s >> t;
    long long cs[26] = {0}, ct[26] = {0}, q = 0;
    for (char c : s) {
        if (c == '?') q++;
        else cs[c - 'a']++;
    }
    for (char c : t) ct[c - 'a']++;
    auto need = [&](long long k) {
        long long r = 0;
        for (int c = 0; c < 26; c++)
            if (ct[c]) r += max(0LL, k * ct[c] - cs[c]);
        return r;
    };
    long long lo = 0, hi = (long long)s.size();
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (need(mid) <= q) lo = mid;
        else hi = mid - 1;
    }
    long long add[26];
    for (int c = 0; c < 26; c++)
        add[c] = ct[c] ? max(0LL, lo * ct[c] - cs[c]) : 0;
    int c = 0;
    for (char &ch : s) {
        if (ch != '?') continue;
        while (c < 26 && add[c] == 0) c++;
        if (c < 26) { ch = 'a' + c; add[c]--; }
        else ch = 'a';
    }
    cout << s << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, k;
    cin >> n >> k;
    vector<long long> c(n + 1);
    for (int i = 1; i <= n; i++) cin >> c[i];
    // time slots k+1..k+n; at each slot pick the max-cost flight already released (index <= slot)
    priority_queue<pair<long long, int>> pq;
    vector<int> t(n + 1);
    long long cost = 0;
    int nxt = 1;
    for (int slot = k + 1; slot <= k + n; slot++) {
        while (nxt <= n && nxt <= slot) {
            pq.push({c[nxt], nxt});
            nxt++;
        }
        auto [cc, i] = pq.top();
        pq.pop();
        t[i] = slot;
        cost += cc * (slot - i);
    }
    cout << cost << "\n";
    for (int i = 1; i <= n; i++) cout << t[i] << (i == n ? "\n" : " ");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    long long a, b, f, k;
    cin >> a >> b >> f >> k;
    if (f > b) { cout << -1 << "\n"; return 0; }
    // k visits to the station f, one per journey; refuel only when the next leg is unreachable
    long long fuel = b - f;  // at first visit
    long long cnt = 0;
    for (long long j = 1; j <= k; j++) {
        bool odd = (j % 2 == 1);
        long long D;             // distance from this visit to the next visit (or to the end)
        if (j == k) D = odd ? a - f : f;
        else D = odd ? 2 * (a - f) : 2 * f;
        if (fuel < D) {
            if (b < D) { cout << -1 << "\n"; return 0; }
            cnt++;
            fuel = b;
        }
        fuel -= D;
    }
    cout << cnt << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<int> a(n), rem(n + 1, 0);
    for (auto &x : a) {
        scanf("%d", &x);
        rem[x]++;
    }
    vector<char> present(n + 1, 0);
    for (int x : a) present[x] = 1;
    vector<int> miss;
    for (int v = 1; v <= n; v++)
        if (!present[v]) miss.push_back(v);
    int q = miss.size(), ptr = 0;
    vector<char> kept(n + 1, 0);
    for (int i = 0; i < n; i++) {
        int v = a[i];
        rem[v]--;  // occurrences of v after position i
        bool change;
        if (kept[v]) change = true;                        // value already kept once
        else if (rem[v] == 0) { kept[v] = 1; change = false; }  // last copy, keep it
        else if (ptr < q && miss[ptr] < v) change = true;  // a smaller missing value is available
        else { kept[v] = 1; change = false; }
        if (change) a[i] = miss[ptr++];
    }
    printf("%d\n", q);
    for (int i = 0; i < n; i++) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<int> p(n + 1);
    for (int i = 1; i <= n; i++) cin >> p[i];
    vector<char> vis(n + 1, 0);
    vector<long long> len;
    for (int i = 1; i <= n; i++) {
        if (vis[i]) continue;
        long long L = 0;
        for (int j = i; !vis[j]; j = p[j]) {
            vis[j] = 1;
            L++;
        }
        len.push_back(L);
    }
    if (len.size() == 1) {
        cout << (long long)n * n << "\n";
        return 0;
    }
    sort(len.rbegin(), len.rend());
    // one swap of two targets merges the two largest cycles
    long long ans = 0;
    for (size_t i = 2; i < len.size(); i++) ans += len[i] * len[i];
    ans += (len[0] + len[1]) * (len[0] + len[1]);
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    string s1, s2;
    cin >> s1 >> s2;
    int m = s1.size();
    // nx[i][c] = first index >= i in s1 with letter c, or -1
    vector<array<int, 26>> nx(m + 1);
    nx[m].fill(-1);
    for (int i = m - 1; i >= 0; i--) {
        nx[i] = nx[i + 1];
        nx[i][s1[i] - 'a'] = i;
    }
    long long copies = 1;
    int p = 0;
    for (char ch : s2) {
        int c = ch - 'a';
        if (nx[0][c] < 0) { cout << -1 << "\n"; return 0; }
        int j = nx[p][c];
        if (j < 0) {  // start a new copy of s1
            copies++;
            j = nx[0][c];
        }
        p = j + 1;
    }
    cout << copies << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<array<long long, 3>> s(n);  // (l, -r, index)
    for (int i = 0; i < n; i++) {
        long long l, r;
        scanf("%lld %lld", &l, &r);
        s[i] = {l, -r, i + 1};
    }
    sort(s.begin(), s.end());  // l ascending, r descending on ties
    long long mx = LLONG_MIN;
    int mi = -1;
    for (auto &x : s) {
        long long r = -x[1];
        if (r <= mx) {  // inside the segment with the largest r seen so far
            printf("%lld %d\n", x[2], mi);
            return 0;
        }
        if (r > mx) {
            mx = r;
            mi = (int)x[2];
        }
    }
    printf("-1 -1\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    long long n, k, l;
    cin >> n >> k >> l;
    long long m = n * k;
    vector<long long> a(m);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    // every barrel volume is >= a[0] (the smallest stave is a volume) and <= a[0] + l
    long long p = upper_bound(a.begin(), a.end(), a[0] + l) - a.begin();
    // j-th smallest volume (1-based) must sit at sorted index <= (j-1)*k; choose the largest feasible indices
    vector<long long> q(n + 2);
    q[n + 1] = p;
    for (long long j = n; j >= 1; j--) q[j] = min((j - 1) * k, q[j + 1] - 1);
    if (q[1] != 0) {
        cout << 0 << "\n";
        return 0;
    }
    long long ans = 0;
    for (long long j = 1; j <= n; j++) ans += a[q[j]];
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    long long n, x, y;
    cin >> n >> x >> y;
    string s;
    cin >> s;
    long long g = 0;  // number of maximal zero-blocks
    for (int i = 0; i < n; i++)
        if (s[i] == '0' && (i == 0 || s[i - 1] == '1')) g++;
    if (g == 0) {
        cout << 0 << "\n";
        return 0;
    }
    // invert one block for y; each further block costs min(x, y) (reverse merges blocks, or invert it)
    cout << y + (g - 1) * min(x, y) << "\n";
    return 0;
}
